/* Merlin — Prospect Research Mission Control
   Static app: brief -> master prompt -> (AI platform researches) -> results desk.
   No backend, no scraping: Merlin writes the brief and receives the results. */
"use strict";

/* ---------- Gold-standard workbook architecture (mirrors the reference ski workbooks) ---------- */
const CONTACTS_COLUMNS = [
  "Business name","Region","Operator / client","Published email","Suggested greeting","Contact use",
  "Address / branches","Email source URL","Evidence type","Location source URL","Notes","Checked",
  "Outreach status","Shared inbox","Record ID","Contact ID","Contact name","Job title / department",
  "Eligibility","Eligibility reason","Verification date","Outreach stage","Last sent date","Sent by",
  "Total messages sent","Latest delivery evidence","Last reply date","Reply outcome","Next action",
  "Next action date","Owner","Instagram handle","IG verification","IG verification notes"
];
const DIRECTORY_COLUMNS = [
  "Business name","Region","Operator / client","Official website","Published emails","Phone",
  "Address / location","Email source URL","Evidence type","Operating status","Notes","Checked",
  "Record ID","Instagram handle","IG verification","IG verification notes"
];
const HELD_COLUMNS = CONTACTS_COLUMNS.slice(0, 15);
const COVERAGE_COLUMNS = ["Region","Directory entries","Unique contacts","Primary contacts","Areas without email"];
const ACTIVITY_COLUMNS = [
  "Activity ID","Contact ID","Business / operator ID","Date and time","Event type","Campaign / purpose",
  "Subject","Message or thread link","Sample / creative version","Outcome","Failure code / explanation",
  "Recorded by","Notes"
];
const SUPPRESSION_COLUMNS = ["Email address or domain","Scope","Reason","Date recorded","Evidence link","Review condition"];
const IG_LABELS = ["Verified","Probable","Not found"];

/* ---------- View switching ---------- */
const tabs = document.querySelectorAll(".tab");
function showView(name){
  tabs.forEach(t=>{
    const on = t.dataset.view===name;
    t.classList.toggle("is-active", on);
    t.setAttribute("aria-selected", on ? "true" : "false");
  });
  document.querySelectorAll(".view").forEach(v=>v.classList.toggle("is-active", v.id==="view-"+name));
  if(name==="prompt") renderPrompt();
  window.scrollTo({top:0, behavior:"smooth"});
}
tabs.forEach(t=>t.addEventListener("click", ()=>showView(t.dataset.view)));
document.getElementById("go-prompt").addEventListener("click", ()=>showView("prompt"));

/* ---------- Brief -> master prompt ---------- */
const $ = id => document.getElementById(id).value.trim();
function brief(){
  return {
    name: $("f-name") || "the user",
    business: $("f-business"),
    role: $("f-role") || "service provider",
    service: $("f-service"),
    industry: $("f-industry") || "the target industry",
    niche: $("f-niche"),
    geo: $("f-geo") || "the target geography",
    type: $("f-type"),
    count: $("f-count") || "100",
    prefix: ($("f-prefix") || "RSCH").toUpperCase(),
    collect: {
      contact: document.getElementById("d-contact").checked,
      website: document.getElementById("d-website").checked,
      ig: document.getElementById("d-ig").checked,
      phone: document.getElementById("d-phone").checked,
      address: document.getElementById("d-address").checked
    }
  };
}
function todayISO(){ return new Date().toISOString().slice(0,10); }

function buildPrompt(b){
  const want = ["Published email (always)", "Source URL for every researched field (always)", "Evidence type for every researched field (always)"];
  if(b.collect.contact) want.push("Named contact person and their job title / department");
  if(b.collect.website) want.push("Official website (place it on the Directory tab and link rows by Record ID)");
  if(b.collect.ig) want.push("Instagram handle with a verification label (Verified / Probable / Not found) and short verification notes");
  if(b.collect.phone) want.push("Published phone number");
  if(b.collect.address) want.push("Address / location");

  return `MASTER PROSPECT RESEARCH PROMPT — generated by Merlin
========================================================

ROLE
You are an elite prospect-research analyst working to the "Super Intelligence" standard:
never settle for the first pass. Push deeper with multiple independent sources until the
realistic ceiling is reached. Accuracy beats volume: a smaller list that is fully verified
is worth more than a long list of guesses.

THE MISSION
I am ${b.name}${b.business ? ` of ${b.business}` : ""}, a ${b.role}.
I sell: ${b.service}.
Find ${b.count} prospect clients I can pitch my work to.
- Industry: ${b.industry}
- Sub-niche: ${b.niche || "the whole industry, no sub-niche restriction"}
- Geography: ${b.geo}
- Prospect type: ${b.type}

WHERE TO SCOUR (use ALL of these, not just the first that answers)
1. Official websites — contact pages, team / staff pages, press and media pages, footers.
2. Press releases and media coverage — they often name media contacts and direct inboxes.
3. Page source and structured data (JSON-LD) on official sites — emails hide there.
4. Industry directories and associations — member lists, official operator directories.
5. Business listings and review platforms (Google Business, Yelp, TripAdvisor and peers).
6. Instagram — find each prospect's official account and verify it (protocol below).
7. Location sources — confirm the business actually operates where the list claims.

WHAT TO COLLECT FOR EVERY PROSPECT
${want.map(w=>"- "+w).join("\n")}

NON-NEGOTIABLE QUALITY RULES
1. PUBLISHED EMAILS ONLY. Every email must be copied from a public source you actually
   opened. NEVER guess an address, never build one from a pattern (no invented
   firstname@, info@, contact@). A prospect with no published email goes on the Directory
   tab marked "no published email found" — it does not get a fabricated Contacts row.
2. EVIDENCE ON EVERY FIELD. Each researched field carries a source URL and an evidence
   type (for example: Official website, Published ski/business directory, Press release,
   Association listing, Review platform).
3. VERIFY BEFORE YOU WRITE. Cross-check each email on at least one second source where
   one exists. If a value cannot be verified, say so in Notes instead of smoothing it over.
4. DEDUPE. One Contacts row per unique email. If several businesses share one inbox,
   flag "Shared inbox = Yes" and combine the businesses on that row so nobody is pitched twice.
5. SUPPRESSION. Any address or domain that is dead, undeliverable-looking (no mail routing),
   a known double failure, or marked do-not-contact goes on the Suppression register with a
   reason — never silently back into the list. If I gave you a suppression list, honour it.
6. HELD, NOT DELETED. Closed, paused, ineligible or unverifiable prospects go on Held
   contacts with the reason — they are never quietly dropped.
7. NOTES KEEP HISTORY. The Notes column preserves status history; append, never overwrite.
8. HONEST GAPS. Report what you could not find as plainly as what you found. "Not found"
   is an acceptable, respected answer. A guess is not.

INSTAGRAM VERIFICATION PROTOCOL
For each prospect, find the official Instagram account and label it exactly one of:
- Verified — the handle is confirmed as the business's own account (linked from the
  official website, or unambiguously the business by name, location and content).
- Probable — a strong candidate exists but could not be confirmed from an official source;
  explain the doubt in the verification notes.
- Not found — no official account could be established; say what was searched. A fan,
  template or unrelated account is NOT the business's handle.
Record the evidence for the label in "IG verification notes". Never present a guess as Verified.

OUTPUT — A GOLD-STANDARD WORKBOOK, DELIVERED AS TAB-READY TABLES
Return the research as separate tables, one per tab, CSV or TSV, with EXACTLY these
headers, in this order. Every row carries a Record ID (${b.prefix}-0001, ${b.prefix}-0002, ...)
and a Checked date (the research date, YYYY-MM-DD; today is ${todayISO()}).

TAB 1 — About: purpose of the workbook, scope, research date, headline counts (main
contacts, unique emails, held contacts, directory entries, areas without email), how to
use it, the verification boundary ("published does not mean delivery-tested"), and the
SENDING RULES block below.

TAB 2 — Contacts (the master list), columns:
${CONTACTS_COLUMNS.join(" | ")}
Leave the outreach-execution columns (Outreach stage, Last sent date, Sent by, Total
messages sent, Latest delivery evidence, Last reply date, Reply outcome, Next action,
Next action date) empty for fresh research, set Outreach status to
"Researched — not yet contacted", and set Eligibility with a one-line Eligibility reason.

TAB 3 — Directory (every business found, contacted or not), columns:
${DIRECTORY_COLUMNS.join(" | ")}

TAB 4 — Held contacts: the first 15 Contacts columns, with the hold reason in Notes.

TAB 5 — Coverage rollup, columns:
${COVERAGE_COLUMNS.join(" | ")}

TAB 6 — Activity log, columns:
${ACTIVITY_COLUMNS.join(" | ")}
Log one row for this research run itself, under Recorded by = your platform/operator name.

TAB 7 — Suppression register, columns:
${SUPPRESSION_COLUMNS.join(" | ")}

SENDING RULES — PRINT THESE ON THE ABOUT TAB, VERBATIM IN SPIRIT
(These rules protect the sender's account; blocks are driven by rejected messages.)
1. ONE SENDER ONLY. No parallel sending runs, ever.
2. The workbook is the only queue. Read the Notes column before sending any row; a row
   marked DO NOT RESEND is binding.
3. Never a third attempt to an address that has failed twice. Dead is dead.
4. Every address must pass a drafting-safe check before use: published source, valid
   format, live domain with mail routing. Never send on hope.
5. Pace sends; bursts trip rate limits far below daily ceilings.
6. On the first sending-limit notice: stop everything, report, wait for the owner's word.
7. After every send outcome, update that row's Notes, Outreach status and Sent by
   (operator attribution) in the same pass.

CROSS-PLATFORM VERIFICATION ACCESS
This workbook must be built for a second pair of eyes. The finished sheet must be
accessible to a SECOND, different AI platform — not the one that produced it — with
READ AND WRITE access, so that platform can independently verify the research for
robustness:
- Re-open the source URL behind each published email and confirm the address is really
  published there and belongs to that business.
- Confirm each Instagram handle exists, belongs to the business, and that its
  verification label (Verified / Probable / Not found) is honest.
- Check for duplicates (the same email twice, the same business under two names) and
  for any address that belongs on the Suppression register instead of the list.
Then the verifying platform WRITES its findings back into this same record:
- Update the Checked date and the verification / status fields it re-confirmed.
- APPEND to Notes — verification never overwrites the original researcher's notes.
- Log the verification pass in the Activity log with Recorded by naming the verifying
  platform/operator, so the sheet itself shows who researched and who checked.
Deliver the workbook somewhere the second platform can open and edit it — for example
a shared spreadsheet with edit access — not as a locked file only you hold.

CLOSE THE RUN WITH A SUMMARY: how many prospects per tab, coverage by region, how many
emails are single-source vs cross-checked, how many Instagram handles landed in each
verification label, and an honest list of gaps (areas without email, unverifiable values).`;
}

function renderPrompt(){
  const b = brief();
  document.getElementById("prompt-out").value = buildPrompt(b);
  document.getElementById("prompt-meta").textContent =
    `${b.industry} · ${b.geo} · target ${b.count} prospects · Record IDs ${b.prefix}-####`;
}
document.getElementById("regen-prompt").addEventListener("click", renderPrompt);
document.getElementById("copy-prompt").addEventListener("click", async ()=>{
  const ta = document.getElementById("prompt-out");
  ta.select();
  try{ await navigator.clipboard.writeText(ta.value); }
  catch(e){ document.execCommand("copy"); }
  const btn = document.getElementById("copy-prompt");
  const old = btn.textContent; btn.textContent = "Copied ✓";
  setTimeout(()=>btn.textContent = old, 1600);
});

/* ---------- Results viewer ---------- */
const SAMPLE_CSV = "Business name,Region,Operator / client,Published email,Suggested greeting,Contact use,Address / branches,Email source URL,Evidence type,Location source URL,Notes,Checked,Outreach status,Shared inbox,Record ID,Contact ID,Contact name,Job title / department,Eligibility,Eligibility reason,Verification date,Outreach stage,Last sent date,Sent by,Total messages sent,Latest delivery evidence,Last reply date,Reply outcome,Next action,Next action date,Owner,Instagram handle,IG verification,IG verification notes\nSAMPLE \u2014 Aurora Peak Lodge (fictional),Colorado,Aurora Peak Lodge LLC,hello@aurorapeaklodge.example.com,\"Dear Aurora Peak Lodge team,\",General / published business contact,\"1200 Sample Ridge Road, Aspen, CO (fictional)\",https://example.com/aurora-peak-lodge/contact,Official website,https://example.com/aurora-peak-lodge,\"SAMPLE ROW \u2014 fictional demo data, not a real business. Published contact page lists a marketing manager by name.\",2026-10-17,Researched \u2014 not yet contacted,No,SMP-0001,SAMPLE CONTACT 0001,Jamie Rivers (fictional),Marketing Manager,Eligible,\"Operating, published marketing contact, fits the brief.\",2026-10-17,,,,,,,,,,Sample Operator,@aurorapeaklodge.example,Verified,Handle linked from the official website footer.\nSAMPLE \u2014 Bluebird Family Ski Hill (fictional),Vermont,Bluebird Ski Cooperative,info@bluebirdskihill.example.com,\"Dear Bluebird team,\",General / published business contact,\"48 Sample Hollow Lane, Stowe, VT (fictional)\",https://example.com/bluebird/contact,Published ski directory,https://example.com/bluebird,SAMPLE ROW \u2014 fictional demo data. Shared inbox for two sister hills; combined on one row to prevent duplicate pitches.,2026-10-17,Researched \u2014 not yet contacted,Yes,SMP-0002,SAMPLE CONTACT 0002,,,Eligible,Operating co-operative with a published general inbox.,2026-10-17,,,,,,,,,,Sample Operator,@bluebirdskihill.example,Probable,\"Account name and photos match the hill, but it is not linked from the official website; confirmation outstanding.\"\nSAMPLE \u2014 Cascade Indoor Snow Centre (fictional),New Jersey,Cascade Snow Group,events@cascadesnow.example.com,\"Dear Cascade Snow team,\",Events / group bookings contact,\"1 Sample Plaza, East Rutherford, NJ (fictional)\",https://example.com/cascade/events,Official website,https://example.com/cascade,SAMPLE ROW \u2014 fictional demo data. Events inbox preferred over general inbox for creative pitches.,2026-10-17,Contacted \u2014 awaiting reply,No,SMP-0003,SAMPLE CONTACT 0003,Priya Nair (fictional),Events Lead,Eligible,Named events contact published on the official site.,2026-10-17,First outreach sent,2026-10-15,Sample Operator,1,No bounce or failure notice received,,,,,Sample Operator,@cascadesnow.example,Verified,Handle printed on the venue's official events page.\nSAMPLE \u2014 Driftline Backcountry Guides (fictional),British Columbia,Driftline Guides Inc.,bookings@driftlineguides.example.com,\"Dear Driftline team,\",Bookings / published business contact,\"900 Sample Creek Road, Revelstoke, BC (fictional)\",https://example.com/driftline/book,Association listing,https://example.com/driftline,SAMPLE ROW \u2014 fictional demo data. Guide association listing corroborates the website address.,2026-10-17,Researched \u2014 not yet contacted,No,SMP-0004,SAMPLE CONTACT 0004,Marco Chen (fictional),Owner / Lead Guide,Eligible,Owner named publicly; bookings inbox published in two sources.,2026-10-17,,,,,,,,,,Sample Operator,,Not found,\"Searched Instagram and the official site; only a fan photography account exists, which is not the business's handle.\"\nSAMPLE \u2014 Ember & Oak Mountain Caf\u00e9 (fictional),Utah,Ember & Oak Hospitality,catering@emberandoak.example.com,\"Dear Ember & Oak team,\",Catering / secondary contact,\"77 Sample Canyon Drive, Park City, UT (fictional)\",https://example.com/emberandoak/catering,Review platform,https://example.com/emberandoak,\"SAMPLE ROW \u2014 fictional demo data. Secondary contact: catering inbox, not the first choice for a creative pitch.\",2026-10-17,Replied \u2014 in conversation,No,SMP-0005,SAMPLE CONTACT 0005,Sofia Marino (fictional),Catering Manager,Eligible,Published on the official catering page and a review platform.,2026-10-17,Reply received,2026-10-12,Sample Operator,2,Reply received 2026-10-14,2026-10-14,Asked for portfolio examples,Send sample reel link,2026-10-19,Sample Operator,@emberandoakcafe.example,Verified,Handle matches the caf\u00e9's signage photos and is linked from Google Business profile.\nSAMPLE \u2014 Frostfield Night Skiing (fictional),Wisconsin,Frostfield Recreation Co.,office@frostfieldnight.example.com,\"Dear Frostfield team,\",General / published business contact,\"310 Sample Lights Road, Madison, WI (fictional)\",https://example.com/frostfield/contact,Published business listing,https://example.com/frostfield,SAMPLE ROW \u2014 fictional demo data. Single-source email so far; flagged in Notes for a second-source check before any send.,2026-10-17,Published directory contact; review before outreach,No,SMP-0006,SAMPLE CONTACT 0006,,,Needs verification,Existing publication research retained; not yet independently verified.,,,,,,,,,,,Sample Operator,@frostfieldnights.example,Probable,\"Recent posts show the hill's lifts and name, but no link from the official website confirms ownership.\"\n";
let rows = [];       // array of objects keyed by the file's own headers
let headers = [];    // headers of the loaded CSV

function parseCSV(text){
  const out = []; let row = [], field = "", inQ = false;
  const s = text.replace(/\r\n/g, "\n").replace(/\r/g, "\n");
  for(let i=0;i<s.length;i++){
    const c = s[i];
    if(inQ){
      if(c === '"'){ if(s[i+1] === '"'){ field += '"'; i++; } else inQ = false; }
      else field += c;
    } else if(c === '"'){ inQ = true; }
    else if(c === ","){ row.push(field); field = ""; }
    else if(c === "\n"){ row.push(field); field = ""; out.push(row); row = []; }
    else field += c;
  }
  if(field.length || row.length){ row.push(field); out.push(row); }
  const clean = out.filter(r => r.some(c => String(c).trim() !== ""));
  if(!clean.length) return {headers: [], rows: []};
  const hdrs = clean[0].map(h => String(h).trim());
  const objs = clean.slice(1).map(r=>{
    const o = {}; hdrs.forEach((h,idx)=> o[h] = (r[idx] ?? "").toString().trim()); return o;
  });
  return {headers: hdrs, rows: objs};
}
function csvCell(v){
  const s = (v ?? "").toString();
  return /[",\n]/.test(s) ? '"' + s.replace(/"/g,'""') + '"' : s;
}
function toCSV(hdrs, objs){
  return [hdrs.join(","), ...objs.map(o => hdrs.map(h => csvCell(o[h])).join(","))].join("\n");
}
function download(name, text, type){
  const blob = new Blob([text], {type: type || "text/plain;charset=utf-8"});
  const a = document.createElement("a");
  a.href = URL.createObjectURL(blob); a.download = name;
  document.body.appendChild(a); a.click(); a.remove();
  setTimeout(()=>URL.revokeObjectURL(a.href), 4000);
}

function setData(parsed, sourceLabel){
  headers = parsed.headers; rows = parsed.rows;
  const sel = document.getElementById("flt-status");
  sel.innerHTML = '<option value="">Outreach status: all</option>';
  [...new Set(rows.map(r => r["Outreach status"]).filter(Boolean))].sort()
    .forEach(s => { const o = document.createElement("option"); o.textContent = s; sel.appendChild(o); });
  document.getElementById("csv-in").dataset.source = sourceLabel || "";
  renderResults();
}
function igClass(label){
  if(label === "Verified") return "ig-verified";
  if(label === "Probable") return "ig-probable";
  return "ig-notfound";
}
function filteredRows(){
  const q = document.getElementById("q").value.toLowerCase();
  const ig = document.getElementById("flt-ig").value;
  const st = document.getElementById("flt-status").value;
  return rows.filter(r=>{
    if(ig && (r["IG verification"] || "Not found") !== ig) return false;
    if(st && r["Outreach status"] !== st) return false;
    if(q && !Object.values(r).join(" ").toLowerCase().includes(q)) return false;
    return true;
  });
}
function renderResults(){
  const list = filteredRows();
  document.getElementById("count-line").textContent =
    rows.length ? `Showing ${list.length} of ${rows.length} prospects` : "";
  const cnt = l => rows.filter(r => (r["IG verification"] || "Not found") === l).length;
  document.getElementById("stats").innerHTML = rows.length ? [
    `<span class="stat">Total <b>${rows.length}</b></span>`,
    `<span class="stat">With published email <b>${rows.filter(r=>r["Published email"]).length}</b></span>`,
    `<span class="stat">IG Verified <b>${cnt("Verified")}</b></span>`,
    `<span class="stat">IG Probable <b>${cnt("Probable")}</b></span>`,
    `<span class="stat">IG Not found <b>${cnt("Not found")}</b></span>`
  ].join("") : "";

  const cards = document.getElementById("cards");
  cards.innerHTML = list.slice(0, 60).map(r=>`
    <article class="card">
      <h3>${esc(r["Business name"] || "(unnamed)")}</h3>
      <p class="sub">${esc(r["Region"] || "")}${r["Operator / client"] ? " · " + esc(r["Operator / client"]) : ""}${r["Record ID"] ? " · " + esc(r["Record ID"]) : ""}</p>
      <p><b>Email:</b> ${esc(r["Published email"] || "— no published email —")}</p>
      ${r["Contact name"] ? `<p><b>Contact:</b> ${esc(r["Contact name"])}${r["Job title / department"] ? " — " + esc(r["Job title / department"]) : ""}</p>` : ""}
      ${r["Address / branches"] ? `<p><b>Where:</b> ${esc(r["Address / branches"])}</p>` : ""}
      <div>
        ${r["Instagram handle"] ? `<span class="chip ${igClass(r["IG verification"])}">${esc(r["Instagram handle"])} · IG ${esc(r["IG verification"] || "Not found")}</span>` : `<span class="chip ig-notfound">No IG handle</span>`}
        ${r["Outreach status"] ? `<span class="chip status">${esc(r["Outreach status"])}</span>` : ""}
        ${r["Evidence type"] ? `<span class="chip">${esc(r["Evidence type"])}</span>` : ""}
      </div>
      ${r["Notes"] ? `<p>${esc(r["Notes"])}</p>` : ""}
    </article>`).join("") ||
    `<p class="empty">${rows.length ? "No prospects match the current filters." : "No data loaded yet — paste a Contacts CSV, open a file, or load the sample."}</p>`;

  const thead = document.querySelector("#grid thead");
  const tbody = document.querySelector("#grid tbody");
  if(!headers.length){ thead.innerHTML = ""; tbody.innerHTML = ""; return; }
  thead.innerHTML = "<tr>" + headers.map(h=>`<th>${esc(h)}</th>`).join("") + "</tr>";
  tbody.innerHTML = list.map(r =>
    "<tr>" + headers.map(h=>`<td title="${esc(r[h])}">${esc(r[h])}</td>`).join("") + "</tr>").join("");
}
function esc(v){
  return (v ?? "").toString().replace(/[&<>"']/g, c =>
    ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
}
["q","flt-ig","flt-status"].forEach(id =>
  document.getElementById(id).addEventListener("input", renderResults));

document.getElementById("parse-paste").addEventListener("click", ()=>{
  const text = document.getElementById("csv-in").value;
  if(!text.trim()){ alert("Paste a Contacts CSV first — or load the sample."); return; }
  setData(parseCSV(text), "pasted");
});
document.getElementById("load-sample").addEventListener("click", async ()=>{
  try{
    const res = await fetch("sample-data.csv");
    if(!res.ok) throw new Error("fetch failed");
    const text = await res.text();
    document.getElementById("csv-in").value = text;
    setData(parseCSV(text), "sample file");
  }catch(e){
    document.getElementById("csv-in").value = SAMPLE_CSV;
    setData(parseCSV(SAMPLE_CSV), "sample (embedded)");
  }
});
document.getElementById("file-in").addEventListener("change", ev=>{
  const f = ev.target.files[0]; if(!f) return;
  const reader = new FileReader();
  reader.onload = ()=>{ document.getElementById("csv-in").value = reader.result; setData(parseCSV(reader.result), f.name); };
  reader.readAsText(f);
});
document.getElementById("export-csv").addEventListener("click", ()=>{
  if(!rows.length){ alert("Load some results first."); return; }
  const normalized = rows.map(r=>{
    const o = {}; CONTACTS_COLUMNS.forEach(h => o[h] = r[h] ?? ""); return o;
  });
  download("merlin-contacts.csv", toCSV(CONTACTS_COLUMNS, normalized), "text/csv;charset=utf-8");
});
document.getElementById("export-template").addEventListener("click", ()=>{
  download("TEMPLATE.md", TEMPLATE_MD, "text/markdown;charset=utf-8");
});

/* ---------- Workbook structure template (also shipped as TEMPLATE.md in the repo) ---------- */
const TEMPLATE_MD = `# Merlin — Gold-Standard Workbook Template

Every Merlin research run produces a workbook with these seven tabs, in this order.
The architecture mirrors two reference outreach workbooks (ski-resort US and Canada
editions), generalised for any industry.

## Tab 1 — About
Purpose of the workbook, scope, research date, headline counts (main contact records,
unique emails, primary / secondary contacts, held records, directory entries, regions
represented, areas without email), how to use the list, publication evidence note,
verification boundary ("published does not mean delivery-tested"), the SENDING RULES
block, and the OPERATOR ATTRIBUTION note (every send is recorded under the name of the
person who made it — the owner or any operator on the team — in the Sent by column and the
Activity log's Recorded by column, in the same pass as the send).

## Tab 2 — Contacts (master list)
${CONTACTS_COLUMNS.join(" | ")}

One row per unique published email. Notes preserve status history — append, never
overwrite. Outreach columns are filled in by whichever operator makes contact, in the
same pass as the contact. The final three columns (Instagram handle, IG verification,
IG verification notes) mirror the Directory tab's Instagram fields inline so the flat
Contacts export works as a standalone CRM file; in the workbook they also live on the
Directory tab, keyed by Record ID.

## Tab 3 — Directory (every business found, contacted or not)
${DIRECTORY_COLUMNS.join(" | ")}

IG verification is exactly one of: Verified (confirmed as the business's own account
from an official source), Probable (strong candidate, unconfirmed — doubt explained in
the notes), Not found (searched, no official account established; a fan or template
account is not a handle).

## Tab 4 — Held contacts
${HELD_COLUMNS.join(" | ")}

Prospects held back (closed, paused, ineligible, unverifiable) with the reason in
Notes. Held means parked with a reason, never deleted.

## Tab 5 — Coverage rollup
${COVERAGE_COLUMNS.join(" | ")}

## Tab 6 — Activity log
${ACTIVITY_COLUMNS.join(" | ")}

Every action on the workbook, attributed with Recorded by.

## Tab 7 — Suppression register
${SUPPRESSION_COLUMNS.join(" | ")}

Addresses and domains that must never be contacted (dead domains, double failures,
do-not-contact). A suppression earned in one workbook is honoured in every other
workbook where the same address appears.
`;
